  metadata: Scalars["JSONObject"];
  /** The issue this attachment was moved from, for example when its issue was marked as a duplicate. Null if no original issue is recorded. The issue field identifies where the attachment belongs now. */
  originalIssue?: Maybe<Issue>;
  /** Details identifying the application or integration that created the attachment. Null if no source is recorded. */
  source?: Maybe<Scalars["JSONObject"]>;
