/** A workspace as seen during sign-in and workspace discovery. Its ID identifies the workspace, while urlKey identifies its URL. Sign-in settings explain how an account may gain access; appearing in discovery results does not mean the account already has a membership. */
export type AuthOrganization = {
  __typename?: "AuthOrganization";
  /**
   * Allowed authentication providers, empty array means all are allowed
   * @deprecated Use authSettings.allowedAuthServices instead.
   */
  allowedAuthServices: Array<Scalars["String"]>;
  /** An approximate count of users, updated once per day. */
  approximateUserCount: Scalars["Float"];
  /** JSON object describing workspace sign-in requirements, including allowedAuthServices and role-based exceptions. Use the available and locked membership lists in the authentication response to determine whether the current sign-in method grants this account access. */
  authSettings: Scalars["JSONObject"];
  /** Hosting cell used to route requests for this workspace. */
  cell: Scalars["String"];
  /** The time at which the entity was created. */
  createdAt: Scalars["DateTime"];
  /** Time when workspace deletion was requested. Null when deletion has not been requested. */
  deletionRequestedAt?: Maybe<Scalars["DateTime"]>;
  /** Whether the workspace is enabled for access. */
  enabled: Scalars["Boolean"];
  /** Whether signup hides other workspaces for users whose email domain is claimed by this workspace. */
  hideNonPrimaryOrganizations: Scalars["Boolean"];
  /** The unique identifier of the entity. */
  id: Scalars["ID"];
  /** Workspace logo URL. Null when no logo is set. */
  logoUrl?: Maybe<Scalars["String"]>;
  /** Workspace name. */
  name: Scalars["String"];
  /** Up to three previous workspace URL slugs that redirect to the current slug. */
  previousUrlKeys: Array<Scalars["String"]>;
  /** Region where the workspace is hosted. */
  region: Scalars["String"];
  /** Feature release channel for the workspace. */
  releaseChannel: ReleaseChannel;
  /** Whether SAML sign-in is enabled for the workspace. */
  samlEnabled: Scalars["Boolean"];
  /** Whether SCIM provisioning is enabled for the workspace. */
  scimEnabled: Scalars["Boolean"];
  /** Email domain or URL slug associated with the workspace. */
  serviceId: Scalars["String"];
  /** Workspace identifier used in its Linear URL. This can change when the workspace is renamed; use id when you need a stable reference. */
  urlKey: Scalars["String"];
  /** Active user count, excluding app users. Null when the caller cannot view the count or it was not fetched. */
  userCount?: Maybe<Scalars["Float"]>;
};

/** A signed-in account and the workspaces it can access or join. One account can have a separate user identity in each workspace: id is the account ID, while each users entry has its own workspace user ID. Locked entries require a different sign-in method. Authentication is carried by the session cookie, not the deprecated token field. */
export type AuthResolverResponse = {
  __typename?: "AuthResolverResponse";
  /** Whether the account may join workspaces through its email domain. Null when no decision was returned. */
  allowDomainAccess?: Maybe<Scalars["Boolean"]>;
  /** Workspaces the account may join through its email domain or an invitation. These are opportunities to join, not existing memberships. Null means this part of workspace discovery was not provided. */
  availableOrganizations?: Maybe<Array<AuthOrganization>>;
  /** Email for the authenticated account. */
  email: Scalars["String"];
  /** User account ID. */
  id: Scalars["String"];
  /** UUID of the workspace last accessed by the account. Null when no previous workspace is recorded. */
  lastUsedOrganizationId?: Maybe<Scalars["String"]>;
  /** Workspaces discovered for the account that require another sign-in method before it can join. Null means this part of workspace discovery was not provided. */
  lockedOrganizations?: Maybe<Array<AuthOrganization>>;
  /** Existing workspace memberships that require another sign-in method. These users belong to the account, but this authentication cannot open their workspaces until the required sign-in is completed. */
  lockedUsers: Array<AuthUser>;
  /** The authentication service used for the current session (e.g., google, email, saml). */
  service?: Maybe<Scalars["String"]>;
  /**
   * Always null. Authentication is returned through the session cookie.
   * @deprecated Deprecated and not used anymore. Never populated.
   */
  token?: Maybe<Scalars["String"]>;
  /** Active workspace memberships available with this sign-in method. Each entry is the account's user identity in one workspace; an empty list does not prevent the account from joining an available workspace. */
  users: Array<AuthUser>;
};

/** An account's user identity in one workspace, including its role and profile there. Use id when referring to this workspace membership; userAccountId links the same person's identities across workspaces. The organization field identifies the workspace for this user. */
export type AuthUser = {
  __typename?: "AuthUser";
  /** Whether this workspace membership is active. A disabled membership cannot access the workspace; an active membership can still require a different sign-in method according to workspace policy. */
  active: Scalars["Boolean"];
  /** Avatar image URL. Null when no avatar is set. */
  avatarUrl?: Maybe<Scalars["String"]>;
  /** The time at which the entity was created. */
  createdAt: Scalars["DateTime"];
  /** Display name, unique within the workspace. */
  displayName: Scalars["String"];
  /** The user's email address. */
  email: Scalars["String"];
  /** UUID of the workspace user, distinct from the account ID. */
  id: Scalars["ID"];
  /** The user's full name. */
  name: Scalars["String"];
  /** OAuth application UUID for an app user. Null for users created through other sources. */
  oauthClientId?: Maybe<Scalars["String"]>;
  /** Workspace this user identity belongs to. */
  organization: AuthOrganization;
  /** Role of the user in the workspace. */
  role: UserRoleType;
  /** Account UUID shared by this person’s user identities across workspaces. */
  userAccountId: Scalars["String"];
};

