  /** City, region, and country inferred from the recorded IP address. Null when unavailable. */
  location?: Maybe<Scalars["String"]>;
  /** City inferred from the last recorded IP address. Null when unavailable. */
  locationCity?: Maybe<Scalars["String"]>;
  /** Country inferred from the last recorded IP address. Null when unavailable. */
  locationCountry?: Maybe<Scalars["String"]>;
  /** Country code inferred from the last recorded IP address. Null when unavailable. */
  locationCountryCode?: Maybe<Scalars["String"]>;
  /** Region inferred from the last recorded IP address. Null when unavailable. */
  locationRegionCode?: Maybe<Scalars["String"]>;
  /** Display name inferred from the client and operating system, such as a browser on a named OS or Linear iOS. Uses an unknown-device label when there is not enough request information. */
  name: Scalars["String"];
  /** Operating system inferred from the User-Agent header. Null when unknown. */
