  content?: Maybe<Scalars["String"]>;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** The user recorded as the creator of this customer request. Null if no creator was recorded or the user was deleted. */
  creator?: Maybe<User>;
  /** The customer organization this need belongs to. Null if the need has not yet been associated with a customer. */
  customer?: Maybe<Customer>;
  /** The resource's unique UUID. This stays unchanged when the resource is renamed or moved; use it for stored references and mutations. */
  id: Scalars["ID"];
  /** The issue linked to this request. Null for requests linked directly to a project or another source. */
  issue?: Maybe<Issue>;
  /** The original issue recorded when this request moved during an issue merge. Moving the request explicitly with customerNeedUpdate clears this reference. Null when no original issue is recorded or that issue was deleted. */
  originalIssue?: Maybe<Issue>;
  /** Whether the customer need is important or not. 0 = Not important, 1 = Important. */
  priority: Scalars["Float"];
  /** The project linked to this request, either directly or through its issue. Null if no project is associated. */
  project?: Maybe<Project>;
  /** The project attachment linked to this need. Populated when the need originates from an intake source or when a URL is manually provided for a project-level need. Provides a link back to the original source of the customer feedback. Mutually exclusive with attachment. */
  projectAttachment?: Maybe<ProjectAttachment>;
