  /** The time the cycle was closed, or null while it is upcoming or active. A cycle can close before its originally scheduled end, for example when the next cycle is started early. */
  completedAt?: Maybe<Scalars["DateTime"]>;
  /** Daily completed issue counts. Entries align with issueCountHistory. */
  completedIssueCountHistory: Array<Scalars["Float"]>;
  /** Daily completed scope, weighted by the team’s estimation settings. Entries align with scopeHistory. */
  completedScopeHistory: Array<Scalars["Float"]>;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** Description of the cycle’s goals. Null if none is set. */
  description?: Maybe<Scalars["String"]>;
