  scopeHistory: Array<Scalars["Float"]>;
  /** The time the cycle starts. Cycle scheduling uses the team’s time zone, so local start times can have different UTC offsets across daylight-saving changes. */
  startsAt: Scalars["DateTime"];
  /** The team that owns the cycle. */
  team: Team;
