/** Metadata for a saved version of rich-text content. The capture time identifies the content state, while actorIds identifies users whose edits contributed to it. This public type does not include the historical body. */
export type DocumentContentHistoryType = {
  __typename?: "DocumentContentHistoryType";
  /** UUIDs of users whose edits are included in this version. */
  actorIds?: Maybe<Array<Scalars["String"]>>;
  /** The time of the content state captured in this version. It can precede createdAt because saving a new edit may first record the previously stored state. */
  contentDataSnapshotAt: Scalars["DateTime"];
  /** Time the history entry was saved. */
  createdAt: Scalars["DateTime"];
  /** The identifier of the document content that this history entry snapshots. */
  documentContentId: Scalars["String"];
  /** The unique identifier of the document content history entry. */
  id: Scalars["String"];
};

/** Unpublished changes to rich-text content contributed by automations. The live body stays unchanged until the revision is applied. The base and revision states let a compatible editor compare the proposal with the live content it was based on. */
export type DocumentContentRevision = Node & {
  __typename?: "DocumentContentRevision";
  /** When the resource was archived, in UTC. Null while active, including after unarchiving. Archived resources still exist but are normally excluded from lists unless `includeArchived` is true. */
  archivedAt?: Maybe<Scalars["DateTime"]>;
  /** The live document content state this revision was last refreshed from, as a base64-encoded Yjs state update. */
  baseContentState: Scalars["String"];
  /** A hash of the current base and revision content. It identifies the content summarized by this revision when it matches summaryContentHash; treat the hash as an opaque value. */
  contentHash?: Maybe<Scalars["String"]>;
  /** Unpublished content as a base64-encoded Yjs state update. */
  contentState: Scalars["String"];
  /** UUIDs of the workflows that contributed edits to this revision. */
  contributorWorkflowDefinitionIds: Array<Scalars["String"]>;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** The document content that this revision is based on. */
  documentContent: DocumentContent;
  /** The identifier of the document content that this revision is based on. */
  documentContentId: Scalars["String"];
  /** The resource's unique UUID. This stays unchanged when the resource is renamed or moved; use it for stored references and mutations. */
  id: Scalars["ID"];
  /** A short description of the proposed changes. Compare summaryContentHash with contentHash before displaying it as current; the summary can lag behind edits to the revision. */
  summary?: Maybe<Scalars["String"]>;
  /** Content hash used to generate summary. Differs from contentHash while the summary is out of date. */
  summaryContentHash?: Maybe<Scalars["String"]>;
  /** When the resource was last meaningfully updated, in UTC. Some background or housekeeping changes do not advance this timestamp. */
  updatedAt: Scalars["DateTime"];
};

/** The metadata and optional Markdown body for a new document. Choose exactly one container: a project, issue, or release. The document’s UUID identifies its metadata, while a separate DocumentContent record holds its body. */
