/** A strategic goal supported by projects and, optionally, sub-initiatives. An initiative has its own owner, lifecycle status, target date, and written updates. Linking a project to an initiative does not change the project’s teams or issue workflow. */
export type Initiative = Node & {
  __typename?: "Initiative";
  /** When the resource was archived, in UTC. Null while active, including after unarchiving. Archived resources still exist but are normally excluded from lists unless `includeArchived` is true. */
  archivedAt?: Maybe<Scalars["DateTime"]>;
  /** The initiative's color. */
  color?: Maybe<Scalars["String"]>;
  /** The time the initiative entered Completed status. Changing to any other status clears this value. Null when the initiative has no current completion time. */
  completedAt?: Maybe<Scalars["DateTime"]>;
  /** The full initiative overview in Markdown. Null if no overview has been set; description is the separate short summary. */
  content?: Maybe<Scalars["String"]>;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** The user who created the initiative. */
  creator?: Maybe<User>;
  /** A short plain-text summary of the initiative. Use content for its longer Markdown overview. Null if no summary is set. */
  description?: Maybe<Scalars["String"]>;
  /** The document backing the initiative overview. Null if no overview has been set. */
  documentContent?: Maybe<DocumentContent>;
  /** Documents associated with the initiative. */
  documents: DocumentConnection;
  /** The resolution of the reminder frequency. */
  frequencyResolution: FrequencyResolutionType;
  /** The overall health of the initiative, derived from the most recent initiative update. Possible values are onTrack, atRisk, or offTrack. Null if no health has been reported. */
  health?: Maybe<InitiativeUpdateHealthType>;
  /** The time at which the initiative health was last updated, typically when a new initiative update is posted. Null if health has never been set. */
  healthUpdatedAt?: Maybe<Scalars["DateTime"]>;
  /** History entries associated with the initiative. */
  history: InitiativeHistoryConnection;
  /** The icon of the initiative. Can be an emoji or a decorative icon type. */
  icon?: Maybe<Scalars["String"]>;
  /** The resource's unique UUID. This stays unchanged when the resource is renamed or moved; use it for stored references and mutations. */
  id: Scalars["ID"];
  /** Initiative updates associated with the initiative. */
  initiativeUpdates: InitiativeUpdateConnection;
  /** Settings for all integrations associated with that initiative. */
  integrationsSettings?: Maybe<IntegrationsSettings>;
  /** The IDs of the initiative labels associated with this initiative. */
  labelIds: Array<Scalars["String"]>;
  /** Labels associated with this initiative. */
  labels: InitiativeLabelConnection;
  /** The most recent status update posted for this initiative. Null if no updates have been posted. */
  lastUpdate?: Maybe<InitiativeUpdate>;
  /** The team that leads the initiative and determines its visibility. An initiative without a lead team is visible at workspace level. Null if no lead team is assigned. */
  leadTeam?: Maybe<Team>;
  /** Links associated with the initiative. */
  links: EntityExternalLinkConnection;
  /** The name of the initiative. */
  name: Scalars["String"];
  /** The workspace of the initiative. */
  organization: Organization;
  /** The user responsible for the initiative and its status updates. Null if no owner is assigned. */
  owner?: Maybe<User>;
  /** The immediate parent initiative. Null if this is a top-level initiative. */
  parentInitiative?: Maybe<Initiative>;
  /** The priority of the initiative. 0 = No priority, 1 = Urgent, 2 = High, 3 = Medium, 4 = Low. */
  priority: Scalars["Int"];
  /** The sort order of the initiative within the workspace when ordered by priority. */
  prioritySortOrder: Scalars["Float"];
  /** Projects linked to this initiative that you can access. By default, this also includes projects in its sub-initiatives; set includeSubInitiatives to false to return only directly linked projects. */
  projects: ProjectConnection;
  /** The initiative's unique URL slug, used to construct human-readable URLs. */
  slugId: Scalars["String"];
  /** The sort order of the initiative within the workspace. */
  sortOrder: Scalars["Float"];
  /** The time the initiative most recently entered Active status. This is refreshed if the initiative leaves Active and later returns to it. Null if no activation time has been recorded. */
  startedAt?: Maybe<Scalars["DateTime"]>;
  /** The lifecycle status of the initiative. One of Proposed, Planned, Active, Completed, Canceled. */
  status: InitiativeStatus;
  /** The initiative’s direct children. Does not recursively include deeper descendants. */
  subInitiatives: InitiativeConnection;
  /** The estimated completion date of the initiative. Null if no target date is set. */
  targetDate?: Maybe<Scalars["TimelessDate"]>;
  /** The precision of targetDate: month, quarter, halfYear, or year. Null means an exact date or no target date. */
  targetDateResolution?: Maybe<DateResolutionType>;
  /** Whether the initiative is in the trash. Trashed initiatives are also archived and can be restored with initiativeUnarchive while they remain available. Null means the initiative is not trashed. */
  trashed?: Maybe<Scalars["Boolean"]>;
  /** The frequency at which to prompt for updates. When not set, reminders are inherited from workspace. */
  updateReminderFrequency?: Maybe<Scalars["Float"]>;
  /** The n-weekly frequency at which to prompt for updates. When not set, reminders are inherited from workspace. */
  updateReminderFrequencyInWeeks?: Maybe<Scalars["Float"]>;
  /** The day at which to prompt for updates. */
  updateRemindersDay?: Maybe<Day>;
  /** The hour at which to prompt for updates. */
  updateRemindersHour?: Maybe<Scalars["Float"]>;
  /** When the resource was last meaningfully updated, in UTC. Some background or housekeeping changes do not advance this timestamp. */
  updatedAt: Scalars["DateTime"];
  /** The initiative’s URL in Linear. */
  url: Scalars["String"];
  /** The initiative’s visibility, inherited from its lead team. Without a lead team, the initiative is public within the workspace. This does not make it accessible outside the workspace. */
  visibility: InitiativeVisibility;
};

