  attachment?: Maybe<Attachment>;
  /** Identifier of the attachment that was linked to or unlinked from the issue. Can be used to query the attachment directly. Null if no attachment change occurred. */
  attachmentId?: Maybe<Scalars["String"]>;
  /** Whether the issue was auto-archived. */
  autoArchived?: Maybe<Scalars["Boolean"]>;
  /** Whether the issue was auto-closed. */
  autoClosed?: Maybe<Scalars["Boolean"]>;
  /** The bot that performed the action. */
  botActor?: Maybe<ActorBot>;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** [Deprecated] Legacy UUID of a customer request linked to the issue. Not populated for new changes. */
