  /** Identifier of the user from whom the issue was re-assigned. Can be used to query the user directly. Null if the assignee was not changed or the issue was previously unassigned. */
  fromAssigneeId?: Maybe<Scalars["String"]>;
  /** The cycle before this change. Null when none was set, the property did not change, or the recorded resource is no longer available to you. */
  fromCycle?: Maybe<Cycle>;
  /** Identifier of the previous cycle of the issue. Can be used to query the cycle directly. Null if the cycle was not changed or the issue was not in a cycle. */
  fromCycleId?: Maybe<Scalars["String"]>;
  /** The agent delegate before this change. Null when none was set, the property did not change, or the recorded resource is no longer available to you. */
  fromDelegate?: Maybe<User>;
  /** The due date before this change, as YYYY-MM-DD without a time or time zone. Null if there was no due date or this entry does not record a due-date change. */
  fromDueDate?: Maybe<Scalars["TimelessDate"]>;
  /** The estimate before this change, using the team’s numeric estimation scale. Null if no estimate was set or this entry does not record an estimate change. */
  fromEstimate?: Maybe<Scalars["Float"]>;
  /** The parent issue before this change. Null when none was set, the property did not change, or the recorded resource is no longer available to you. */
  fromParent?: Maybe<Issue>;
  /** Identifier of the previous parent issue. Can be used to query the issue directly. Null if the parent was not changed or the issue previously had no parent. */
  fromParentId?: Maybe<Scalars["String"]>;
  /** The priority before this change: 0 = No priority, 1 = Urgent, 2 = High, 3 = Medium, 4 = Low. Null if this entry does not record a priority change. */
  fromPriority?: Maybe<Scalars["Float"]>;
  /** The project before this change. Null when none was set, the property did not change, or the recorded resource is no longer available to you. */
  fromProject?: Maybe<Project>;
  /** Identifier of the previous project of the issue. Can be used to query the project directly. Null if the project was not changed or the issue was not in a project. */
  fromProjectId?: Maybe<Scalars["String"]>;
  /** The project milestone before this change. Null when none was set, the property did not change, or the recorded resource is no longer available to you. */
