  toConvertedProjectId?: Maybe<Scalars["String"]>;
  /** The cycle after this change. Null when the assignment was cleared, the property did not change, or the recorded resource is no longer available to you. */
  toCycle?: Maybe<Cycle>;
  /** Identifier of the new cycle of the issue. Can be used to query the cycle directly. Null if the cycle was not changed or the issue was removed from a cycle. */
  toCycleId?: Maybe<Scalars["String"]>;
