  toDelegate?: Maybe<User>;
  /** The due date after this change, as YYYY-MM-DD without a time or time zone. Null if the date was cleared or this entry does not record a due-date change. */
  toDueDate?: Maybe<Scalars["TimelessDate"]>;
  /** The estimate after this change, using the team’s numeric estimation scale. Null if the estimate was cleared or this entry does not record an estimate change. */
  toEstimate?: Maybe<Scalars["Float"]>;
  /** The parent issue after this change. Null when the assignment was cleared, the property did not change, or the recorded resource is no longer available to you. */
  toParent?: Maybe<Issue>;
  /** Identifier of the new parent issue. Can be used to query the issue directly. Null if the parent was not changed or the issue was removed from its parent. */
  toParentId?: Maybe<Scalars["String"]>;
  /** The priority after this change: 0 = No priority, 1 = Urgent, 2 = High, 3 = Medium, 4 = Low. Null if this entry does not record a priority change. */
  toPriority?: Maybe<Scalars["Float"]>;
  /** The project after this change. Null when the assignment was cleared, the property did not change, or the recorded resource is no longer available to you. */
