  /** New SLA day-counting mode: all for calendar days or onlyBusinessDays for working days. */
  toSlaType?: Maybe<Scalars["String"]>;
  /** The issue status after this change. Null if this entry does not record that change or the recorded resource is no longer available to you. */
  toState?: Maybe<WorkflowState>;
  /** Identifier of the new workflow state (issue status) of the issue. Can be used to query the workflow state directly. Null if the status was not changed. */
