/** A resource with a stable, unique identifier. Use `id` to refer to the same resource across queries and mutations. */
export type Node = {
  /** The resource's unique, stable identifier. Use this value in queries and mutations that accept the resource's ID. */
  id: Scalars["ID"];
};

/** An activity notification sent to a workspace member. Its concrete type identifies the related entity, while type identifies the event that occurred. Read, snooze, and archive states belong to the recipient. The inbox can group several related notifications into one item. */
export type Notification = {
  /** The user that caused the notification. Null if the notification was triggered by a non-user actor such as an integration, external user, or system event. */
  actor?: Maybe<User>;
  /** When the resource was archived, in UTC. Null while active, including after unarchiving. Archived resources still exist but are normally excluded from lists unless `includeArchived` is true. */
  archivedAt?: Maybe<Scalars["DateTime"]>;
  /** The bot that caused the notification. */
  botActor?: Maybe<ActorBot>;
  /** The category of the notification. */
  category: NotificationCategory;
  /** The resource’s recorded creation time, in UTC. Imports may preserve an earlier creation time. */
  createdAt: Scalars["DateTime"];
  /** The time at which an email reminder for this notification was sent to the user. Null if no email reminder has been sent. */
  emailedAt?: Maybe<Scalars["DateTime"]>;
  /** The external user that caused the notification. Populated when the notification was triggered by an external user (e.g., a commenter from a connected integration like Slack or GitHub) rather than a Linear workspace member. */
  externalUserActor?: Maybe<ExternalUser>;
  /** The resource's unique UUID. This stays unchanged when the resource is renamed or moved; use it for stored references and mutations. */
  id: Scalars["ID"];
  /** The time at which the user marked the notification as read. Null if the notification is unread. */
  readAt?: Maybe<Scalars["DateTime"]>;
  /** The time until which a notification is snoozed. After this time, the notification reappears in the user's inbox. Null if the notification is not currently snoozed. */
  snoozedUntilAt?: Maybe<Scalars["DateTime"]>;
  /** Notification type. Determines the kind of event that triggered this notification and which associated entity fields will be populated. */
  type: Scalars["String"];
  /** The time at which a notification was unsnoozed. Null if the notification has not been unsnoozed. */
  unsnoozedAt?: Maybe<Scalars["DateTime"]>;
  /** When the resource was last meaningfully updated, in UTC. Some background or housekeeping changes do not advance this timestamp. */
  updatedAt: Scalars["DateTime"];
  /** The recipient user of this notification. */
  user: User;
};

/** The result of archiving or restoring a resource. */
export type NotificationArchivePayload = ArchivePayload & {
  __typename?: "NotificationArchivePayload";
  /** The resource after the operation, when returned. This can be null when the mutation does not return a resource, including after deletion. Check `success` for the operation's result. */
  entity?: Maybe<Notification>;
  /** Synchronization cursor used by Linear clients. External integrations can ignore this field. */
  lastSyncId: Scalars["Float"];
  /** Whether the operation was successful. */
  success: Scalars["Boolean"];
};

/** Return type for batch notification mutations that operate on multiple notifications at once. */
export type NotificationBatchActionPayload = {
  __typename?: "NotificationBatchActionPayload";
  /** Synchronization cursor used by Linear clients. External integrations can ignore this field. */
  lastSyncId: Scalars["Float"];
  /** The notifications that were updated by the batch operation. */
  notifications: Array<Notification>;
  /** Whether the operation was successful. */
  success: Scalars["Boolean"];
};

/** The categories of notifications a user can subscribe to. */
export enum NotificationCategory {
  AppsAndIntegrations = "appsAndIntegrations",
  Assignments = "assignments",
  Billing = "billing",
  CommentsAndReplies = "commentsAndReplies",
  Customers = "customers",
  DocumentChanges = "documentChanges",
  Feed = "feed",
  Loops = "loops",
  Mentions = "mentions",
  PostsAndUpdates = "postsAndUpdates",
  Reactions = "reactions",
  Reminders = "reminders",
  Reviews = "reviews",
  StatusChanges = "statusChanges",
  Subscriptions = "subscriptions",
  System = "system",
  Triage = "triage",
}

