/** The delivery channels a user can receive notifications in. */
export enum NotificationChannel {
  Desktop = "desktop",
  Email = "email",
  Mobile = "mobile",
  Slack = "slack",
}

/** Whether each delivery channel is enabled. A notification also needs its category enabled for that channel. */
export type NotificationChannelPreferences = {
  __typename?: "NotificationChannelPreferences";
  /** Whether notifications are currently enabled for desktop. */
  desktop: Scalars["Boolean"];
  /** Whether notifications are currently enabled for email. */
  email: Scalars["Boolean"];
  /** Whether notifications are currently enabled for mobile. */
  mobile: Scalars["Boolean"];
  /** Whether notifications are currently enabled for Slack. */
  slack: Scalars["Boolean"];
};

/** A page of results. Read `nodes` for the resources, or `edges` if you also need a cursor for each result. Use `pageInfo` to fetch further pages; a connection may contain fewer results than the requested page size. */
export type NotificationConnection = {
  __typename?: "NotificationConnection";
  /** The page's results paired with their cursors. */
  edges: Array<NotificationEdge>;
  /** The resources on this page, in the same order as `edges`. Empty when no results match or no more results remain in the requested direction. */
  nodes: Array<Notification>;
  /** Cursors and availability of pages before and after this one. */
  pageInfo: PageInfo;
};

